def f(datasets):
    res = []
    from collections import Counter
    for n, k, s, data in datasets:
        cnt = Counter()
        cost = 0
        for a, b, c in data:
            cnt[a * b] += 1
            cost += c
            if cost > s:
                cnt = Counter()
                cost = 0
            if len(cnt) == k:
                if k == 1:
                    res.extend([a, b] for a, b in cnt.items())
                else:
                    res.append((a, b, k) for a, b in cnt.items() if data.count((a, b, c)) >= k)
    return [item for sublist in res for item in sublist]
```

